242→// parseHookType parses a specific hook type from rawHooks into the target slice.
243→// Silently ignores parse errors (leaves target unchanged).
244→func parseHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]FactoryHookMatcher) {
245→	if data, ok := rawHooks[hookType]; ok {
246→		//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
247→		json.Unmarshal(data, target)
248→	}
249→}
250→
251→// marshalHookType marshals a hook type back to rawHooks.
252→// If the slice is empty, removes the key from rawHooks.
253→func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, matchers []FactoryHookMatcher) {
254→	if len(matchers) == 0 {
255→		delete(rawHooks, hookType)
256→		return
257→	}
258→	data, err := json.Marshal(matchers)
259→	if err != nil {
260→		return // Silently ignore marshal errors (shouldn't happen)
261→	}
262→	rawHooks[hookType] = data
263→}
